#!/usr/bin/env python3 -I
# Implements prompts/PDF2BIM_VECTOR_PROBE.md §43.16 — writes migration CL009: window families at the DIN 4172 sizes of a German Werkplan scan
# (raster_openings.py openings.json). Same mesh method as gen_window_families.py (§34). Deterministic: same inputs -> same bytes. Witness: W-S19c-e.
# Usage: gen_werkplan_window_families.py <openings.json> <german_werkplan_efh.json> <element_defaults.json> [<earlier CLnnn.sql>,... [<label, default CL009>]] > migration/CLnnn_....sql
#   the 4th argument (§43.18): sizes whose family_id an earlier migration already holds are skipped (migrations are append-only)
import sys, json, os, math
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from family_mesh import TRI, box, along_y, blob
O = json.load(open(sys.argv[1]))['openings']; T = json.load(open(sys.argv[2]))['window_system']
REG = json.load(open(sys.argv[3]))['defaults']
def regv(k): v = REG[k]; return v['value'] if isinstance(v, dict) else v
H = round(float(regv('window.height')) * 1000); F = T['frame_face_mm'] / 1000; P = T['pane_mm'] / 1000
def mesh(w, h, n, d):
    "centred, X width, Y depth, Z height: head and sill run the full width, jambs and mullions between them, one pane per sash (as §34)"
    hw, hh, hd = w / 2, h / 2, d / 2
    b = [box(-hw, hw, -hd, hd, hh - F, hh), box(-hw, hw, -hd, hd, -hh, -hh + F), box(-hw, -hw + F, -hd, hd, -hh + F, hh - F), box(hw - F, hw, -hd, hd, -hh + F, hh - F)]
    clear = (w - 2 * F - (n - 1) * F) / n; x = -hw + F
    for i in range(n):
        b.append(box(x, x + clear, -P / 2, P / 2, -hh + F, hh - F)); x += clear
        if i < n - 1: b.append(box(x, x + F, -hd, hd, -hh + F, hh - F)); x += F
    V = []; I = []
    for q in b:
        o = len(V); V += q; I += [(a + o, c + o, e + o) for a, c, e in TRI]
    return V, I
sizes = sorted({(o['nominal_mm'], round(o['thk_m'] * 1000)) for o in O})
LABEL = sys.argv[5] if len(sys.argv) > 5 else 'CL009'
PRIOR = ''.join(open(f).read() for f in sys.argv[4].split(',')) if len(sys.argv) > 4 else ''
def fid_of(w, d): return '%s_%dx%d' % ('DEWP_W%d' % w + ('' if d == 365 else 'd%d' % d), w, H)
skipped = [w for w, d in sizes if "'%s'" % fid_of(w, d) in PRIOR]; sizes = [(w, d) for w, d in sizes if "'%s'" % fid_of(w, d) not in PRIOR]
print(("-- %s: window families at the DIN 4172 Öffnungsmaß sizes a German Werkplan scan needs, generated by scripts/pdf2bim/gen_werkplan_window_families.py. DO NOT hand-edit: regenerate.\n"
      "-- Spec: prompts/PDF2BIM_VECTOR_PROBE.md §43.16 (owner 2026-11-23). Width: DIN 4172 x*12.5+1 cm. Height: registry window.height. Depth: the wall's READ thickness. Sashes: ceil(w/1250). Frame face, pane: template defaults, YELLOW.\n"
      "-- Data only, append-only, idempotent: INSERT OR IGNORE. Applies to library/component_library.db (never commit the binary: this script is the change)." + ("\n-- Sizes already in an earlier migration, not repeated: %s" % skipped if skipped else "") + "\nBEGIN TRANSACTION;").replace('%s', LABEL, 1))
for w, d in sizes:
    n = math.ceil(w / T['sash_max_mm']); lab = 'DEWP_W%d' % w + ('' if d == 365 else 'd%d' % d); fid = '%s_%dx%d' % (lab, w, H)
    desc = '%s %d×%dmm DIN 4172 opening, %d sash%s, depth %d mm. Generated (German Werkplan type); frame profile is a default.' % (lab, w, H, n, 'es' if n > 1 else '', d)
    print("INSERT OR IGNORE INTO ad_opening_family (family_id,family_name,opening_type,ifc_class,default_width_mm,default_height_mm,is_fire_rated,description,is_active,depth_mm) VALUES ('%s','DE Werkplan window %d sash %dx%dmm','WINDOW','IfcWindow',%d,%d,0,'%s',1,%d);" % (fid, n, w, H, w, H, desc.replace("'", "''"), d))
    V, I = mesh(w / 1000, H / 1000, n, d / 1000); ref = '%s: %d x %d generated' % (lab, w, H); o = w * 100000 + H * 10   # §39: an ordinal no committed row uses
    for VV in (V, along_y(V)):
        v, f, hh = blob(VV, I); o += 1
        print("INSERT OR IGNORE INTO component_geometries (geometry_hash,vertices,faces,normals,vertex_count,face_count) VALUES ('%s',x'%s',x'%s',NULL,%d,%d);" % (hh, v.hex(), f.hex(), len(VV), len(I)))
        print("INSERT OR IGNORE INTO ad_geometry_map (building_type,element_ref,ifc_class,storey,ordinal,geometry_hash,source,provenance) VALUES ('German Werkplan EFH','%s','IfcWindow','Generated',%d,'%s','DIN 4172 + registry, gen_werkplan_window_families.py','PARAMETRIC');" % (ref, o, hh))
print('COMMIT;')
